export function historyFileName(hand,now=new Date()){
 const fallback='Hand-'+hand.number+'.png',blind=hand.blind;
 if(!Number.isSafeInteger(blind)||blind<2||blind%2||!['holdem','plo','plo5','plo6','rush','aof'].includes(hand.variant)||!Number.isFinite(now.getTime()))return fallback;
 const pad=n=>String(n).padStart(2,'0'),hour=now.getUTCHours();
 // Shipped TimeAMPM labels noon AM; preserve its filename behavior.
 return now.getUTCFullYear()+'-'+pad(now.getUTCMonth()+1)+'-'+pad(now.getUTCDate())+'_ '+pad(hour>12?hour-12:hour||12)+'-'+pad(now.getUTCMinutes())+'_'+(hour>12?'PM':'AM')+'_'+blind/2+'_'+blind+'_#'+hand.number+'.png';
}
